STEPS = [('T1', 't1_wide', 'CREATE TABLE bench.out_d1_20261112001649_1.t1_wide AS SELECT ss.ss_ticket_number, ss.ss_item_sk, ss.ss_customer_sk, ss.ss_store_sk, ss.ss_sold_date_sk, d.d_date, d.d_year, d.d_moy, i.i_category, i.i_brand, c.c_customer_id, c.c_birth_year, ca.ca_state, s.s_store_name, ss.ss_quantity, ss.ss_sales_price, ss.ss_ext_sales_price, ss.ss_ext_discount_amt, ss.ss_net_paid FROM store_sales AS ss LEFT JOIN date_dim AS d ON ss.ss_sold_date_sk = d.d_date_sk LEFT JOIN item AS i ON ss.ss_item_sk = i.i_item_sk LEFT JOIN customer AS c ON ss.ss_customer_sk = c.c_customer_sk LEFT JOIN customer_address AS ca ON c.c_current_addr_sk = ca.ca_address_sk LEFT JOIN store AS s ON ss.ss_store_sk = s.s_store_sk'), ('T2', 't2_daily', 'CREATE TABLE bench.out_d1_20261112001649_1.t2_daily AS SELECT d_date, s_store_name, i_category, SUM(ss_ext_sales_price) AS revenue, SUM(ss_quantity) AS qty, SUM(ss_ext_discount_amt) AS discount, COUNT(*) AS lines FROM bench.out_d1_20261112001649_1.t1_wide GROUP BY d_date, s_store_name, i_category'), ('T3', 't3_cust360', "CREATE TABLE bench.out_d1_20261112001649_1.t3_cust360 AS WITH s AS (SELECT ss_customer_sk AS cust, 'store' AS ch, SUM(ss_net_paid) AS paid, COUNT(*) AS n FROM store_sales WHERE NOT ss_customer_sk IS NULL GROUP BY ss_customer_sk), c AS (SELECT cs_bill_customer_sk AS cust, 'catalog' AS ch, SUM(cs_net_paid) AS paid, COUNT(*) AS n FROM catalog_sales WHERE NOT cs_bill_customer_sk IS NULL GROUP BY cs_bill_customer_sk), w AS (SELECT ws_bill_customer_sk AS cust, 'web' AS ch, SUM(ws_net_paid) AS paid, COUNT(*) AS n FROM web_sales WHERE NOT ws_bill_customer_sk IS NULL GROUP BY ws_bill_customer_sk), u AS (SELECT * FROM s UNION ALL SELECT * FROM c UNION ALL SELECT * FROM w) SELECT u.cust, cu.c_customer_id, cu.c_birth_year, ca.ca_state, SUM(u.paid) AS total_paid, SUM(u.n) AS total_lines, SUM(CASE WHEN u.ch = 'store' THEN u.paid ELSE 0 END) AS store_paid, SUM(CASE WHEN u.ch = 'catalog' THEN u.paid ELSE 0 END) AS catalog_paid, SUM(CASE WHEN u.ch = 'web' THEN u.paid ELSE 0 END) AS web_paid FROM u JOIN customer AS cu ON u.cust = cu.c_customer_sk LEFT JOIN customer_address AS ca ON cu.c_current_addr_sk = ca.ca_address_sk GROUP BY u.cust, cu.c_customer_id, cu.c_birth_year, ca.ca_state"), ('T4', 't4a_changes', 'CREATE TABLE bench.out_d1_20261112001649_1.t4_changes AS SELECT ss_ticket_number, ss_item_sk, ss_ext_sales_price * 1.10 AS new_price FROM bench.out_d1_20261112001649_1.t1_wide WHERE (ss_ticket_number * 31 + ss_item_sk) % 100 = 0'), ('T4', 't4b_merge', 'MERGE INTO bench.out_d1_20261112001649_1.t1_wide AS t USING bench.out_d1_20261112001649_1.t4_changes AS u ON t.ss_ticket_number = u.ss_ticket_number AND t.ss_item_sk = u.ss_item_sk WHEN MATCHED THEN UPDATE SET ss_ext_sales_price = u.new_price'), ('T5', 't5_window', 'CREATE TABLE bench.out_d1_20261112001649_1.t5_window AS WITH m AS (SELECT c_customer_id, ca_state, d_year * 12 + d_moy AS mi, SUM(ss_ext_sales_price) AS rev FROM bench.out_d1_20261112001649_1.t1_wide WHERE NOT c_customer_id IS NULL AND NOT d_year IS NULL GROUP BY c_customer_id, ca_state, d_year * 12 + d_moy) SELECT c_customer_id, ca_state, mi, rev, SUM(rev) OVER (PARTITION BY c_customer_id ORDER BY mi NULLS LAST RANGE BETWEEN 11 PRECEDING AND CURRENT ROW) AS trailing12, RANK() OVER (PARTITION BY ca_state, mi ORDER BY rev DESC) AS rnk FROM m')]
CHECKS = {'t1_wide': ['COUNT(*)', 'SUM(ss_ext_sales_price)', 'SUM(ss_quantity)', 'SUM(ss_net_paid)'], 't2_daily': ['COUNT(*)', 'SUM(revenue)', 'SUM(qty)', 'SUM(discount)'], 't3_cust360': ['COUNT(*)', 'SUM(total_paid)', 'SUM(total_lines)', 'SUM(web_paid)'], 't4_changes': ['COUNT(*)', 'SUM(new_price)'], 't5_window': ['COUNT(*)', 'SUM(rev)', 'SUM(trailing12)', 'SUM(rnk)']}
